// Helper Lookup Functions
window.getMoolaScripture = function(scriptureId) {
    if (!window.MOOLA_NOOL_DATABASE || !window.MOOLA_NOOL_DATABASE.scriptures) return null;
    return window.MOOLA_NOOL_DATABASE.scriptures[scriptureId] || null;
};

window.findMoolaVerses = function(query) {
    if (!window.MOOLA_NOOL_DATABASE || !window.MOOLA_NOOL_DATABASE.scriptures) return [];
    var q = query.toLowerCase().trim();
    if (!q) return [];
    var results = [];
    Object.values(window.MOOLA_NOOL_DATABASE.scriptures).forEach(function(sc) {
        sc.sections.forEach(function(sec) {
            sec.verses.forEach(function(v) {
                var match = (v.num && v.num.toLowerCase().includes(q)) ||
                            (v.rootSanskrit && v.rootSanskrit.toLowerCase().includes(q)) ||
                            (v.rootTamilTranslit && v.rootTamilTranslit.toLowerCase().includes(q)) ||
                            (v.bhavartha && v.bhavartha.toLowerCase().includes(q)) ||
                            (v.notes && v.notes.toLowerCase().includes(q));
                if (!match && v.padavurai) {
                    match = v.padavurai.some(function(p) {
                        return p.word.toLowerCase().includes(q) || p.meaning.toLowerCase().includes(q);
                    });
                }
                if (match) {
                    results.push({
                        scriptureId: sc.id,
                        scriptureTitle: sc.title,
                        sectionTitle: sec.title,
                        verse: v
                    });
                }
            });
        });
    });
    return results;
};
